const insightSettingsKey = "insight.settings"

// insightSettings returns the stored settings, or the calibrated defaults
// if none (or invalid ones) are stored.
func (s *server) insightSettings(ctx context.Context) insight.Settings {
	raw, ok, err := s.Store.Setting(ctx, insightSettingsKey)
	if err != nil || !ok {
		return insight.Defaults()
	}
	cfg := insight.Defaults()
	if json.Unmarshal([]byte(raw), &cfg) != nil || !cfg.Valid() {
		return insight.Defaults()
	}
	return cfg
}

// insightInput holds what the rules need for one evaluation.
type insightInput struct {
	cfg     insight.Settings
	series  insight.Series
	fitness map[time.Time]analysis.FitnessDay
	loads   map[time.Time]float64
	q75     float64
}

// loadInsightInput reads the health window and the whole load history (the
// fitness model needs months to build up; ~1,600 rows are cheap).
func (s *server) loadInsightInput(ctx context.Context, today time.Time) (insightInput, error) {
	in := insightInput{cfg: s.insightSettings(ctx), series: insight.Series{}, loads: map[time.Time]float64{},
		fitness: map[time.Time]analysis.FitnessDay{}}
	from := today.AddDate(0, 0, -(in.cfg.WindowDays + in.cfg.WarnDays + 3))
	days, err := s.Store.HealthDays(ctx, from, today, insight.Columns)
	if err != nil {
		return in, err
	}
	for _, d := range days {
		for k, v := range d.Values {
			if f, ok := num(v); ok {
				if in.series[k] == nil {
					in.series[k] = map[time.Time]float64{}
				}
				in.series[k][d.Date] = f
			}
		}
	}
	raw, err := s.Store.DailyLoad(ctx, time.Unix(0, 0).UTC(), today.AddDate(0, 0, 1))
	if err != nil {
		return in, err
	}
	for _, l := range raw {
		if l.Garmin > 0 {
			in.loads[l.Date] = l.Garmin
		}
	}
	for _, f := range analysis.FitnessSeries(in.loads, today) {
		in.fitness[f.Date] = f
	}
	in.q75 = insight.Quantile75(in.loads)
	return in, nil
}

// todayView is the "Heute" card of the dashboard.
type todayView struct {
	HasReadiness bool
	Score        string
	Class        string
	ClassID      string // ready, normal, limited (CSS)
	DayNote      string // set when the readiness refers to yesterday
	Reasons      []string
	Warning      string
	Rec          insight.Recommendation
	RecID        string
}

var classIDs = map[string]string{insight.ClassReady: "ready", insight.ClassNormal: "normal", insight.ClassLimited: "limited"}
var recIDs = map[string]string{insight.RecRest: "rest", insight.RecEasy: "easy", insight.RecModerate: "moderate", insight.RecHard: "hard"}

// today evaluates the readiness of today or, if today has no data yet,
// yesterday (values older than that are not current).
func (s *server) today(ctx context.Context) (*todayView, error) {
	today := localDate(s.now())
	in, err := s.loadInsightInput(ctx, today)
	if err != nil {
		return nil, err
	}
	if len(in.loads) == 0 && len(in.series) == 0 {
		return nil, nil
	}
	v := &todayView{}
	var r *insight.Readiness
	for i, day := range []time.Time{today, today.AddDate(0, 0, -1)} {
		if rd, ok := insight.ComputeReadiness(in.series, in.fitness, day, in.cfg); ok {
			r = &rd
			if i == 1 {
				v.DayNote = "Stand gestern"
			}
			break
		}
	}
	if r != nil {
		v.HasReadiness, v.Score, v.Class, v.ClassID = true, fmt.Sprintf("%.0f", r.Score), r.Class, classIDs[r.Class]
		v.Reasons, v.Warning = r.Reasons, r.Warning
	}
	v.Rec = insight.Recommend(r, in.fitness, in.loads, today, in.q75, in.cfg)
	v.RecID = recIDs[v.Rec.Kind]
	return v, nil
}

// normalNote describes the latest value of a health metric relative to the
// personal normal range, e.g. "↑ 5 bpm über deinem Normal (48–53)".
type normalNote struct {
	Text  string
	Class string // good, bad, neutral
}

func normalNotes(series insight.Series, latest map[string]store.HealthValue, cfg insight.Settings) map[string]normalNote {
	out := map[string]normalNote{}
	for _, m := range []string{insight.RestingHR, insight.HRV, insight.Sleep, insight.BodyHigh, insight.Stress} {
		lv, ok := latest[m]
		if !ok {
			continue
		}
		if m == insight.HRV {
			if note, ok := hrvNote(series, lv.Date); ok {
				out[m] = note
				continue
			}
		}
		d, ok := insight.DeviationOn(series, m, lv.Date, cfg.WindowDays, 14)
		if !ok {
			continue
		}
		lo, hi := d.Normal.Range(m)
		rng := "dein Normal " + insight.FormatRange(m, lo, hi)
		note := normalNote{Text: "im Rahmen · " + rng, Class: "neutral"}
		if d.Band() > 0 {
			diff := d.Value - d.Normal.Median
			arrow, word := "↑", "über"
			if diff < 0 {
				arrow, word = "↓", "unter"
			}
			amount := insight.FormatValue(m, math.Abs(diff))
			if m == insight.Sleep {
				amount = fmt.Sprintf("%.0f min", math.Abs(diff)/60)
			}
			note.Text = fmt.Sprintf("%s %s %s deinem Normal (%s)", arrow, amount, word, insight.FormatRange(m, lo, hi))
			note.Class = "good"
			if d.Z < 0 {
				note.Class = "bad"
			}
		}
		if m == insight.RestingHR {
			note.Text += " · 3-Tage-Schnitt"
		}
		out[m] = note
	}
	return out
}

